create table if not exists subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,plan text not null default 'free' check(plan in('free','pro','agency')),status text not null default 'active',current_period_start timestamptz not null default now(),current_period_end timestamptz,created_at timestamptz not null default now(),unique(user_id));create table if not exists usage_events(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,project_id uuid references projects(id) on delete cascade,event_type text not null,units integer not null default 1,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());create table if not exists report_shares(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,token uuid not null default gen_random_uuid() unique,created_by uuid not null references auth.users(id) on delete cascade,expires_at timestamptz,revoked_at timestamptz,created_at timestamptz not null default now());alter table subscriptions enable row level security;alter table usage_events enable row level security;alter table report_shares enable row level security;create policy "users read subscription" on subscriptions for select using(user_id=auth.uid());create policy "users read usage" on usage_events for select using(user_id=auth.uid());create policy "owners manage report shares" on report_shares for all using(exists(select 1 from projects p where p.id=project_id and p.owner_id=auth.uid()));